def banner(color=True, title=True):
    lines = []
    for row, shades in zip(ART, COLORS):
        line = '  '
        last = None
        for ch, rgb in zip(row, shades):
            if color and rgb != last and ch != ' ':
                r, g, b = rgb
                line += f'\033[38;2;{r};{g};{b}m'
                last = rgb
            line += ch
        lines.append(line + ('\033[0m' if color else ''))
    if title:
        label = 'G R A F A N A'.center(60)
        lines.extend(['', '  ' + ('\033[1;38;2;255;155;30m' if color else '') + label + ('\033[0m' if color else '')])
    return '\n'.join(lines)

if __name__ == '__main__':
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--no-color', action='store_true')
    p.add_argument('--no-title', action='store_true')
    a = p.parse_args()
    print(banner(not a.no_color, not a.no_title))
